import ast
import hashlib
import json
from pathlib import Path

A=Path(__file__).resolve().parent.parent; R=A.parents[2]
OLD=R/"artifacts/science/empd2-nfi-source-telemetry-custody"
def pin(path):
    raw=path.read_bytes(); return {"path":str(path),"sha256":hashlib.sha256(raw).hexdigest(),"bytes":len(raw)}
def put(name,value):
    path=A/name; assert not path.exists(); path.write_text(json.dumps(value,indent=2)+"\n"); return pin(path)
commands=json.loads((A/"source-command-receipts.json").read_bytes()); assert len(commands)==3 and all(row["actual_exit"]==0 for row in commands)
for row in commands:
    for key in ("stdout","stderr"): assert pin(Path(row[key]["path"]))==row[key]
forensics=json.loads((A/"source-forensics.json").read_bytes()); assert forensics["source_only_native_exit"]==0 and len(forensics["help_receipts"])==6 and all(row["actual_exit"]==0 for row in forensics["help_receipts"])
source_files=sorted(A.glob("*.py"),key=lambda p:p.name); assert len(source_files)==11
for path in source_files: ast.parse(path.read_bytes(),filename=str(path))
reused=[]
for name in ("source_runtime.py","runtime_contracts.py","common_runner.py"):
    assert (A/name).read_bytes()==(OLD/name).read_bytes(); reused.append({"name":name,"current":pin(A/name),"predecessor":pin(OLD/name)})
assert pin(A/"common_runner.py")["sha256"]=="9062395231bd7a4ec19bfe41df1587281c06e143b146119fe445a6eb0ce7ce8a"
native_tree=ast.parse((A/"runtime_guarded_runner.py").read_bytes()); prior_tree=ast.parse((OLD/"runtime_guarded_runner.py").read_bytes())
current_functions={node.name:node for node in native_tree.body if isinstance(node,ast.FunctionDef)}
prior_functions={node.name:node for node in prior_tree.body if isinstance(node,ast.FunctionDef)}
assert current_functions.keys()==prior_functions.keys()
scope_replaced=0
class RestoreScope(ast.NodeTransformer):
    def visit_Constant(self,node):
        global scope_replaced
        if isinstance(node.value,str) and "actual current Neotoma publication source epoch" in node.value:
            scope_replaced+=1; return ast.Constant(value=node.value.replace("actual current Neotoma publication source epoch","actual current EMPD2 metadata source epoch"))
        return node
for name,node in current_functions.items():
    reduced=RestoreScope().visit(node)
    assert ast.dump(reduced,include_attributes=False)==ast.dump(prior_functions[name],include_attributes=False),name
assert scope_replaced==1
